{"code": "
import sys

def can_make(x, a, b, k):
    """Check if we can make x cookies with a_i requirements, b_i supplies, and k magic powder"""
    needed = 0
    for ai, bi in zip(a, b):
        needed += max(0, ai * x - bi)
        if needed > k:
            return False
    return needed <= k

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(n)]

    # Binary search for maximum cookies
    low = 0
    high = 10**18  # Large enough upper bound

    while low < high:
        mid = (low + high + 1) // 2
        if can_make(mid, a, b, k):
            low = mid
        else:
            high = mid - 1

    print(low)

if __name__ == "__main__":
    solve()
"}

