def solve():
    n, r = map(int, input().split())
    a = list(map(int, input().split()))

    heaters = []
    for i in range(n):
        if a[i] == 1:
            heaters.append(i + 1)  # 1-indexed

    position = 0
    heaters_used = 0

    while position < n:
        # Find farthest heater covering position
        farthest = -1
        for heater in heaters:
            # Heater covers [heater - r + 1, heater + r - 1]
            start = heater - r + 1
            end = heater + r - 1

            if start <= position <= end:
                if heater > farthest:
                    farthest = heater

        if farthest == -1:
            # No heater covers this position
            return -1

        heaters_used += 1
        # Move to after the end of the coverage range
        position = farthest + r  # Since farthest covers up to farthest + r - 1

    print(heaters_used)

solve()
