import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = [int(data[i + 2]) for i in range(n)]

    best_ops = n  # Worst case: change all trees
    best_changes = []

    # Try each tree as the anchor
    for anchor_idx in range(n):
        anchor = a[anchor_idx]

        # Try anchor height as is, and also check nearby heights
        for c in range(max(1, anchor - 100), min(anchor + 100, 1000) + 1):
            # Set anchor tree to c
            # Compute target heights for all trees
            target = [0] * n
            target[anchor_idx] = c

            for i in range(n):
                if k > 0:
                    target[i] = c + (i - anchor_idx) * k
                else:
                    target[i] = c + (i - anchor_idx) * k

            # Ensure all target heights are positive
            if any(t <= 0 for t in target):
                continue

            # Count operations and record them
            ops = 0
            changes = []
            for j in range(n):
                if a[j] == target[j]:
                    continue
                if a[j] < target[j]:
                    changes.append((j + 1, 'add', target[j] - a[j]))
                else:
                    changes.append((j + 1, 'subtract', a[j] - target[j]))
                ops += 1

            # Update best
            if ops < best_ops or (ops == best_ops and len(changes) < len(best_changes)):
                best_ops = ops
                best_changes = changes

    print(best_ops)
    for change in best_changes:
        print(f"{change[1]} {change[0]} {change[2]}")

if __name__ == "__main__":
    solve()
"}

