import sys

def count_transitions(s):
    count = 0
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            count += 1
    return count

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # Original transitions
    orig_trans = count_transitions(s)

    max_trans = orig_trans

    # Try flipping every possible substring
    for i in range(n):
        for j in range(i, n):
            # Flip s[i:j+1]
            modified = list(s)
            for k in range(i, j + 1):
                modified[k] = '1' if modified[k] == '0' else '0'

            trans = count_transitions(''.join(modified))
            max_trans = max(max_trans, trans)

    print(max_trans)

if __name__ == '__main__':
    solve()
"}

