open_bracket = s.find('[')
close_bracket = s.rfind(']')

# Check if we can form an accordion
if open_bracket == -1 or close_bracket == -1 or open_bracket >= close_bracket:
    print(-1)
else:
    # Find the first two colons after the opening bracket
    colons = []
    for char in s[open_bracket + 1:close_bracket]:
        if char == ':':
            colons.append(len(colons) + 2)  # 2 for the brackets themselves

    if len(colons) < 2:
        print(-1)
    else:
        # Count vertical lines between the first two colons
        # The first colon is at index colons[0] in the original string
        # The second colon is at index colons[1] in the original string
        # Count | between them
        vertical_lines = 0
        for char in s[colons[0] + 1:colons[1]]:
            if char == '|':
                vertical_lines += 1

        # Length = 2 (brackets) + 2 (colons) + vertical_lines
        print(4 + vertical_lines)
