def is_tolerable(s):
    n = len(s)
    # Check for palindromes of length 2
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            return False
    # Check for palindromes of length 3
    for i in range(n - 2):
        if s[i] == s[i + 2]:
            return False
    return True

def find_next_tolerable(n, p, s):
    # Convert string to list for easy modification
    chars = list(s)

    # Try to find the next tolerable string
    for i in range(n - 1, -1, -1):
        # Try to increment the character at position i
        current_char = ord(chars[i]) - ord('a')  # 0-indexed relative to 'a'
        for next_char in range(current_char + 1, p):
            chars[i] = chr(next_char + ord('a'))

            # Check if the string is tolerable
            # We need to check the whole string
            if is_tolerable(chars):
                return ''.join(chars)

            # If not tolerable, backtrack
            chars[i] = chr(current_char + ord('a'))

    # If no tolerable string found
    return "NO"

# Read input
n, p = map(int, input().split())
s = input()

# Find and print the next tolerable string
