{"code": "
def count_magic_up_to(n, b):
    if n == 0:
        return 0

    # Convert n to base-b representation
    digits = []
    num = n
    while num > 0:
        digits.append(num % b)
        num //= b

    # DP: dp[pos][mask] = count of valid numbers
    # pos: current position (0-indexed from left)
    # mask: tuple of counts of each digit modulo 2 (length b)
    # mask is represented as a tuple of 0s and 1s where 0 means even, 1 means odd

    memo = {}

    def dfs(pos, mask):
        if pos == len(digits):
            # Check if all digits have even count (mask is all zeros)
            return 1 if mask == tuple([0]*b) else 0

        if (pos, mask) in memo:
            return memo[(pos, mask)]

        total = 0

        # Try each possible digit d for current position
        for d in range(b):
            new_mask = list(mask)
            new_mask[d] = (new_mask[d] + 1) % 2
            new_mask = tuple(new_mask)

            # If we're at the first position, digit must be non-zero
            if pos == 0 and d == 0:
                continue

            total += dfs(pos + 1, new_mask)

        memo[(pos, mask)] = total
        return total

    result = dfs(0, tuple([0]*b))
    return result

q = int(input())
for _ in range(q):
    b, l, r = map(int, input().split())

    def count_magic_range(l, r):
        return count_magic_up_to(r, b) - count_magic_up_to(l - 1, b)

    print(count_magic_range(l, r))
