middle_row = n
num_rows = 2 * n + 1

for i in range(num_rows):
    # Calculate leading spaces
    if i < middle_row:
        leading_spaces = 2 * (middle_row - i)
    elif i == middle_row:
        leading_spaces = 0
    else:
        leading_spaces = 2 * (i - middle_row)

    # Calculate the digit sequence
    if i == middle_row:
        # Middle row has digits from 0 to n then back to 0
        k = n
    elif i < middle_row:
        # Above middle row: digits go from 0 to (middle_row - i) then back to 0
        k = middle_row - i
    else:
        # Below middle row: digits go from (i - middle_row) then back to 0
        k = i - middle_row

    digits = []
    for j in range(k + 1):
        digits.append(str(j))
    for j in range(k):
        digits.append(str(k - j - 1))

    # Print the line
    print(' ' * leading_spaces + ' '.join(digits))
