def solve():
    n = int(input())
    tree = [[] for _ in range(n + 1)]
    edges = [[] for _ in range(n + 1)]
    is_problem = [False] * (n + 1)

    for i in range(1, n):
        x, y, t = map(int, input().split())
        tree[x].append((y, t))
        tree[y].append((x, t))
        edges[x].append(y)
        edges[y].append(x)
        is_problem[i] = t == 2

    selected = []

    def dfs(node, parent):
        # Check if all edges from this node are problem roads
        problem_count = 0
        non_problem_count = 0

        for neighbor, t in tree[node]:
            if neighbor == parent:
                continue
            if t == 2:
                problem_count += 1
            else:
                non_problem_count += 1

        # If all edges are problem roads, we need to select this node or one of its children
        if problem_count > 0 and non_problem_count == 0:
            selected.append(node)
            # Mark all edges on the path from node to root as covered
            current = node
            while current != 1:
                parent = None
                for neighbor, t in tree[current]:
                    if neighbor != parent:
                        parent = neighbor
                        if t == 2:
                            is_problem[t] = True
                        break
                current = parent

        # Otherwise, just continue DFS
        for neighbor, t in tree[node]:
            if neighbor != parent:
                dfs(neighbor, node)

    dfs(1, -1)

    print(len(selected))
    if selected:
        print(' '.join(map(str, selected)))

solve()
