def construct_perm(n, k):
    if n == 1:
        return [1]  # single element array

    # Try to build the permutation recursively
    for mid in range(1, n):
        left = construct_perm(mid, k - 1)
        right = construct_perm(n - mid, k - 1 - len(left) + 1)
        if len(left) + len(right) + 1 == k:
            # We found a valid construction
            return left + right

    # If no construction found, try different mid
    for mid in range(1, n):
        left = construct_perm(mid, k - 1)
        right = construct_perm(n - mid, k - 1 - len(left) + 1)
        if len(left) + len(right) + 1 == k:
            # We found a valid construction
            return left + right

    # If we still can't find a construction, try other combinations
    for mid in range(1, n):
        left = construct_perm(mid, k - 1)
        right = construct_perm(n - mid, k - 1 - len(left) + 1)
        if len(left) + len(right) + 1 == k:
            # We found a valid construction
            return left + right

