import sys

def min_moves_to_divisible_by_k(a, k):
    """Return minimum moves to make all elements divisible by k"""
    n = len(a)

    # Calculate how many chocolates should go to each box
    # If choc[i] > 0, we need to move them to the right
    # If choc[i] < 0, we need to move them from the left
    choc = [0] * n
    for i in range(n):
        if a[i] % k == 0:
            choc[i] = 0
        else:
            rem = a[i] % k
            if rem < 0:
                rem += k
            choc[i] = rem

    # Move chocolates from left to right greedily
    moves = 0
    for i in range(n):
        if choc[i] > 0:
            moves += abs(choc[i])
            choc[i + 1] += choc[i]  # Move to next box
            choc[i] = 0

    return moves

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    # Try all possible k from 2 to max(a_i) + 1
    max_k = max(a) + 1
    min_moves = float('inf')

    for k in range(2, max_k + 1):
        moves = min_moves_to_divisible_by_k(a, k)
        min_moves = min(min_moves, moves)

    if min_moves == float('inf'):
        print(-1)
    else:
        print(min_moves)

