    cell_to_pos = {}
    for col in range(n):
        cell_to_pos[col + 1] = (0, col)
        cell_to_pos[n + 1 + col] = (1, col)

    # BFS from start to find shortest path to end
    def bfs(start, end):
        if start == end:
            return 0

        # Convert start and end to (row, col)
        (start_r, start_c) = cell_to_pos[start]
        (end_r, end_c) = cell_to_pos[end]

        # Check if either cell is an obstacle
        if row1[start_c] == 'X':
            return -1
        if row1[end_c] == 'X':
            return -1

        # BFS
        visited = [False] * (2 * n)
        queue = [(start_r, start_c, 0)]
        visited[start_r * n + start_c] = True

        while queue:
            r, c, dist = queue.pop(0)

            # Check if we reached the destination
            if r == end_r and c == end_c:
                return dist

            # Try all four directions
            directions = [(0, 1), (1, 0), (0, -1), (1,  0)]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                # Check boundaries and if the cell is empty
                if 0 <= nr < 2 and 0 <= nc < n:
                    # Check if the destination cell is empty
                    if (nr == 0 and row1[nc] == '.') or (nr == 1 and row2[nc] == '.'): 
                        if not visited[nr * n + nc]:
                            visited[nr * n + nc] = True
                            queue.append((nr, nc, dist + 1))

        return -1

    for _ in range(m):
        v, u = map(int, input().split())
        print(bfs(v, u))

n, m = map(int, input().split())
row1 = input().strip()
row2 = input().strip()
solve_maze(n, m, row1, row2)

