def solve() -> None:
    MOD = 10**9 + 7
    s = sys.stdin.readline().strip()
    q = int(sys.stdin.readline())
    queries = []
    for _ in range(q):
        x, y = map(int, sys.stdin.readline().split())
        queries.append((x - 1, y - 1))

    n = len(s)
    total = n // 2
    count = Counter(s)

    # Precompute factorials
    factorial = [1] * (total + 1)
    for i in range(1, total + 1):
        factorial[i] = factorial[i - 1] * i % MOD

    # Compute denominator
    denominator = 1
    for c in count.values():
        for i in range(1, c + 1):
            denominator = denominator * i % MOD

    # Compute factor_half = (n/2)!^2 / product of factorials of counts
    numerator = factorial[total] * factorial[total] % MOD
    factor_half = numerator * pow(denominator, MOD - 2, MOD) % MOD

    # Separate characters
    large = []  # (count, char)
    singles = []  # (char)

    for char, cnt in count.items():
        if cnt > 1:
            large.append((cnt, char))
        else:
            singles.append(char)

