        """Count number of valid assignments where both c and d are in first half."""
        if both_in_first:
            # c and d must be in first half
            c_included = True
            d_included = True
        else:
            c_included = False
            d_included = False

        # Use DP
        dp = defaultdict(int)
        dp[0] = 1

        # Process large characters first
        for cnt, char in large:
            new_dp = defaultdict(int)
            for sum_val, ways in dp.items():
                # Option 1: exclude this character
                new_dp[sum_val] = (new_dp[sum_val] + ways) % MOD

                # Option 2: include this character
                if char == s[c]:
                    if both_in_first:
                        # c must be in first half, so we can include it
                        new_dp[sum_val + cnt] = (new_dp[sum_val + cnt] + ways) % MOD
                    elif not both_in_first:
                        # c must not be in first half, so we cannot include it
                        pass
                elif char == s[d]:
                    if both_in_first:
                        new_dp[sum_val + cnt] = (new_dp[sum_val + cnt] + ways) % MOD
                    elif not both_in_first:
                        # d must not be in first half, so we cannot include it
                        pass
                else:
                    new_dp[sum_val + cnt] = (new_dp[sum_val + cnt] + ways) % MOD
            dp = new_dp

        # Now process single characters
