                    if both_in_first:
                        new_dp[sum_val + 1] = (new_dp[sum_val + 1] + ways) % MOD
                    elif not both_in_first:
                        pass
                else:
                    new_dp[sum_val + 1] = (new_dp[sum_val + 1] + ways) % MOD
            dp = new_dp

        # Return the number of ways to achieve total sum
        return dp.get(total, 0)

