import sys

def solve():
    input = sys.stdin.read().split()
    if not input:
        return
    N = int(input[0])
    strings = input[1:N+1]

    # Precompute parity masks for each character (a-z)
    # Each bit represents whether the count of that character is odd (1) or even (0)
    # We'll use a 26-bit integer mask

    even_counts = {}
    odd_counts = {}

    for s in strings:
        length = len(s)
        parity = 0
        for ch in s:
            idx = ord(ch) - ord('a')
            parity ^= (1 << idx)

        if length % 2 == 0:
            even_counts[parity] = even_counts.get(parity, 0) + 1
        else:
            odd_counts[parity] = odd_counts.get(parity, 0) + 1

    # Count valid pairs
    answer = 0

    # Even-even with same parity
    total_even = sum(even_counts.values())
    for cnt in even_counts.values():
        answer += cnt * (cnt - 1) // 2

    # Odd-odd with same parity
    total_odd = sum(odd_counts.values())
    for cnt in odd_counts.values():
        answer += cnt * (cnt - 1) // 2

    # Even-odd with different parity
    for parity, cnt_even in even_counts.items():
        # Number of odd strings with parity different from parity
        # = total_odd - odd_counts.get(parity, 0)
        answer += cnt_even * (total_odd - odd_counts.get(parity, 0))

    print(answer)

if __name__ == "__main__":
    solve()
"}

