def get_divisors(n):
    """Get all divisors of n in increasing order"""
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sorted(divisors)

def solve():
    X, k = map(int, input().split())

    # Start with the sequence containing just X
    current = [X]

    # While k > 0 and we haven't stabilized
    while k > 0:
        # Find all elements in the current sequence
        elements = set(current)

        # If all elements are 1, we've stabilized
        if all(e == 1 for e in elements):
            break

        # Build the next sequence
        next_seq = []
        for e in elements:
            next_seq.extend(get_divisors(e))

        # Update current sequence and decrement k
        current = next_seq
        k -= 1

    # Output up to 100,000 elements
    print(' '.join(map(str, current[:100000])))

solve()
