def count_magic_numbers_in_range(base, l, r):
    """Count magic numbers between l and r (inclusive) in the given base"""

    def count(n):
        """Count magic numbers from 1 to n (inclusive) in the given base"""
        if n == 0:
            return 0

        # Convert n to its base representation
        digits = []
        temp = n
        while temp > 0:
            digits.append(temp % base)
            temp //= base
        digits.reverse()

        # DP: dp[pos][mask][tight] = count of valid numbers from position pos
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, mask, tight):
            if pos == len(digits):
                # All digits processed, check if all digits have appeared even number of times
                # mask should be 0
                return 1 if mask == 0 else 0

            limit = digits[pos] if tight else base - 1
            total = 0

            for d in range(0, limit + 1):
                new_tight = tight and (d == limit)
                new_mask = mask

                # Update the mask for digit d
                # Each bit represents the parity of that digit
                new_mask ^= (1 << d)

                total += dp(pos + 1, new_mask, new_tight)

            return total

        # Start with mask 0, position 0, and tight constraint
        return dp(0, 0, True)

    return count(r) - count(l - 1)

q = int(input())
for _ in range(q):
    b, l, r = map(int, input().split())

    # Handle edge case: l = 0
    if l == 0:
        print(count_magic_numbers_in_range(b, 1, r))
    else:
        print(count_magic_numbers_in_range(b, l, r))
