def solve():
    n = int(input())
    p = list(map(int, input().split()))

    from collections import defaultdict, deque

    # dp[jeff_turn] = minimum expected moves from state s when it's Jeff's turn
    # dp[furik_turn] = expected moves from state s when it's Furik's turn

    memo_jeff = dict()
    memo_furik = dict()

    def to_tuple(state):
        return tuple(state)

    def is_sorted(state):
        return all(state[i] < state[i+1] for i in range(len(state)-1))

    def from_tuple(t):
        return list(t)

    def get_expectation(state):
        if is_sorted(state):
            return 0.0

        t = to_tuple(state)
        if t in memo_furik:
            return memo_furik[t]

        decreasing = []
        for i in range(len(state)-1):
            if state[i] > state[i+1]:
                decreasing.append(i)

        increasing = []
        for i in range(len(state)-1):
            if state[i] < state[i+1]:
                increasing.append(i)

        num_decreasing = len(decreasing)
        num_increasing = len(increasing)

        if num_decreasing == 0 and num_increasing == 0:
            memo_furik[t] = 0.0
            return 0.0

        avg_decreasing = 0.0
        for i in decreasing:
            new_state = from_tuple(t)
            new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
            avg_decreasing += get_jeff(new_state)
        avg_decreasing /= num_decreasing if num_decreasing > 0 else 1.0

        avg_increasing = 0.0
        for i in increasing:
            new_state = from_tuple(t)
            new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
            avg_increasing += get_jeff(new_state)
        avg_increasing /= num_increasing if num_increasing > 0 else 1.0

        result = 0.5 * (1.0 + avg_decreasing) + 0.5 * (1.0 + avg_increasing)
        memo_furik[t] = result
        return result

    def get_jeff(state):
        if is_sorted(state):
            return 0.0

        t = to_tuple(state)
        if t in memo_jeff:
            return memo_jeff[t]

        min_expect = float('inf')
        for i in range(len(state)-1):
            new_state = list(t)
            new_state[i], new_state[i+1] = new_state[i+1], new_state[i]
            expect = get_expectation(new_state)
            min_expect = min(min_expect, 1.0 + expect)

        memo_jeff[t] = min_expect
        return min_expect

    start_state = p
    result = get_jeff(start_state)
    print(f"{result:.6f}")

solve()
