import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    max_len = 0
    left = 0
    violations = 0

    for right in range(n):
        # Check if current element violates the strictly increasing property
        if right > 0 and a[right] <= a[right - 1]:
            violations += 1

        # If we have more than one violation, move left forward
        while violations > 1:
            if left < right and a[left] >= a[left + 1]:
                violations -= 1
            left += 1

        max_len = max(max_len, right - left + 1)

    print(max_len)

if __name__ == "__main__":
    solve()
