from math import gcd

def is_pairwise_coprime(arr):
    """Check if all elements in arr are pairwise coprime"""
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if gcd(arr[i], arr[j]) != 1:
                return False
    return True

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    b = a[:]

    for i in range(n):
        # Check if b[0..i] is pairwise coprime
        if i == 0:
            b[0] = max(a[0], 2)
            continue

        # Check if current prefix is pairwise coprime
        if is_pairwise_coprime(b[:i+1]):
            continue

        # If not, we need to increment b[i] until we find a valid value
        while True:
            b[i] += 1
            # Ensure we maintain the condition b >= a
            if b[i] >= a[i] and is_pairwise_coprime(b[:i+1]):
                break

    print(' '.join(map(str, b)))

solve()
