# Convert cell numbers to (row, col) coordinates (0-indexed)
def get_pos(cell):
    if 1 <= cell <= n:
        return (0, cell - 1)
    else:
        return (1, cell - n - 1)

# BFS to find shortest path from start to end
from collections import deque

def bfs(start, end):
    if start == end:
        return 0
    visited = [[False] * n for _ in range(2)]
    queue = deque([(start, 0)])
    visited[start[0]][start[1]] = True

    while queue:
        pos, dist = queue.popleft()
        r, c = pos

        # Check all four directions
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc

            # Check if new position is valid
            if 0 <= nr < 2 and 0 <= nc < n and not visited[nr][nc]:
                # Check if cell is empty
                if (nr == 0 and row1[nc] == '.') or (nr == 1 and row2[nc] == '.'): 
                    if (nr, nc) == end:
                        return dist + 1
                    visited[nr][nc] = True
                    queue.append(((nr, nc), dist + 1))
    return -1

# Process queries
for _ in range(m):
    v, u = map(int, input().split())
    start = get_pos(v)
    end = get_pos(u)
    print(bfs(start, end))
