import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    events = []
    for _ in range(2 * n):
        events.append(next(it))
        if events[-1] == '-':
            events[-1] += ' ' + next(it)

    # Check validity
    place_time = [None] * (n + 1)  # place_time[x] = index of event when shuriken x was placed

    for i, event in enumerate(events):
        if event == '+':
            # We need to decide which shuriken to place
            # Try placing the smallest available shuriken that hasn't been placed yet
            for price in range(1, n + 1):
                if place_time[price] is None:
                    place_time[price] = i
                    break
        else:  # event == '- x'
            price = int(event[2:])

            # Check if this price is available to be placed
            if place_time[price] is None:
                # This shuriken hasn't been placed yet, so it's not available
                print("NO")
                return

            # Check if this is the cheapest available shuriken
            # For all y < price, y must not have been placed between place_time[price] and this event
            for y in range(1, price):
                if place_time[y] is not None and place_time[y] < i and place_time[y] > place_time[price]:
                    # y was placed but not bought, and y < price, so x wouldn't be the cheapest
                    print("NO")
                    return

    # Construct output
    print("YES")
    result = []
    for i in range(len(events)):
        if events[i] == '+':
            # Find which shuriken was placed at this event
            for price in range(1, n + 1):
                if place_time[price] == i:
                    result.append(str(price))
                    break

    print(' '.join(result))

if __name__ == "__main__":
    solve()

