    current = [X]

    for _ in range(k):
        # Compute f(current) by expanding each element into its divisors
        next_seq = []
        for num in current:
            next_seq.extend(get_divisors(num))

        # If we've exceeded 10^5 elements, we're done
        if len(next_seq) >= 10**5:
