left_brackets = [i for i, c in enumerate(s) if c == '[']
right_brackets = [i for i, c in enumerate(s) if c == ']']

max_length = -1

# Try all possible pairs of left and right brackets
for left_idx in left_brackets:
    for right_idx in right_brackets:
        if left_idx >= right_idx:
            continue

        # Find all colons after left_idx
        colons = [i for i, c in enumerate(s) if c == ':' and left_idx < i < right_idx]

        if len(colons) < 1:
            continue

        # Count the number of '|' after the first colon and before the second colon
        # We need to find the best way to choose the colons
        best_count = 0
        for i in range(len(colons)):
            for j in range(i + 1, len(colons)):
                # Count '|' between colons[i] and colons[j]
                count = 0
                for c in s[colons[i]+1:colons[j]]:
                    if c == '|':
                        count += 1

                # Also count '|' before colons[i]
                # and between colons[j] and right_idx
                for k in range(left_idx + 1, colons[i]):
                    if s[k] == '|':
                        count += 1

                for l in range(colons[j]+1, right_idx):
                    if s[l] == '|':
                        count += 1

                best_count = max(best_count, count)

