import itertools

MOD = 998244353

def solve(n, k):
    # Brute force for small n

    # If n is large, we can't brute force
    if n > 10:
        return 0

    # Count ways to place n rooks with exactly one per row and column
    # and exactly k attacking pairs

    count = 0

    # Generate all permutations (one rook per row and column)
    for perm in itertools.permutations(range(n)):
        # Count attacking pairs
        pairs = 0

        # For rows
        for r in range(n):
            cnt = 0
            for c in range(n):
                if perm[c] == r:
                    cnt += 1
                    if cnt > 1:
                        pairs += 1
                        cnt = 1

        # For columns
        for c in range(n):
            cnt = 0
            for r in range(n):
                if perm[r] == c:
                    cnt += 1
                    if cnt > 1:
                        pairs += 1
                        cnt = 1

        if pairs == k:
            count += 1

    return count

# Read input
n, k = map(int, sys.stdin.read().split())

# Solve
