def max_games(n):
    if n == 2:
        return 1
    if n >= 3:
        return 2
    # For n >= 3, we need to see if we can do more than 2

    # Actually, let's think recursively:
    # If winner plays k games, they face k players.
    # Each of these k players must have played at most k-1 games.
    # So we need to add players from previous rounds.

    # For k games, we need:
    # 1 (winner) + 1 (player for k-th game) + 2 (players for k-1-th game) + 4 (players for k-2-th game) + ...
    # = 1 + 2^0 + 2^1 + ... + 2^{k-1}
    # = 2^k players

    # But wait, n=3 needs 3 players, which is 1 + 2^0 + 2^1 = 1+1+2 = 4? No...

    # Let's just implement a better binary search
    left, right = 1, 60
    while left < right:
        mid = (left + right + 1) // 2
        players_needed = 1  # winner
        for i in range(mid):
            players_needed += 1 << i  # 2^i
            if players_needed > n:
                break
        if players_needed <= n:
            left = mid
        else:
            right = mid - 1
    return left

n = int(input())
print(max_games(n))
