import sys
sys.setrecursionlimit(1000000)


def solve():
    s = sys.stdin.readline().strip()

    # Count occurrences of each character
    count = defaultdict(int)
    for c in s:
        count[c] += 1

    # Find which character appears exactly twice
    dup_char = None
    for c in count:
        if count[c] == 2:
            dup_char = c
            break

    if dup_char is None:
        # We need to find which character appears more than once
        # Since there are 26 cells and 27 letters, exactly one character appears twice
        # We'll just pick the first character that appears more than once
        for c in s:
            if count[c] > 1:
                dup_char = c
                break

    # Try to place the string in the grid using backtracking
    grid = [list(' ' * 13) for _ in range(2)]

    def is_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    def backtrack(pos, prev_r, prev_c, used):
        """Backtrack to place the string from position 'pos'
        'used' is a dictionary that tracks how many of each character we've placed"
        """
        if pos == len(s):
            return True

        current_char = s[pos]
        used_count = used[current_char]

        # Try placing current_char at all empty positions
        for r in range(2):
            for c in range(13):
                if grid[r][c] == ' ':
                    if used_count == 0:
                        # First occurrence of this character
                        grid[r][c] = current_char
                        used[current_char] += 1
                        success = backtrack(pos + 1, r, c, used)
                        if success:
                            return True
                        grid[r][c] = ' '
                        used[current_char] -= 1
                    else:
                        # Second occurrence of this character
                        # We can't place it consecutively on the same cell
                        if (prev_r, prev_c) == (r, c):
                            continue
                        if grid[r][c] == ' ':  # Only if we haven't placed this character here yet
                            grid[r][c] = current_char
                            used[current_char] += 1
                            success = backtrack(pos + 1, r, c, used)
                            if success:
                                return True
                            grid[r][c] = ' '
                            used[current_char] -= 1

        return False

    # Try all positions for the duplicate character
    for dup_pos in range(len(s)):
        if count[s[dup_pos]] == 2:
            for dup_row in range(2):
                for dup_col in range(13):
                    # Try placing the duplicate at this position
                    if dup_row == 0 and dup_col == 0:
