def compute_length(s):
    """Compute the length of the longest alternating subsequence"""
    if not s:
        return 0

    # dp[0]: length of longest subsequence ending with s[0]
    # dp[1]: length of longest subsequence ending with a different character
    dp = [1, 1]

    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            # We can extend the subsequence by adding s[i]
            dp[0], dp[1] = dp[1] + 1, dp[0] + 1
        else:
            # We cannot extend the subsequence
            dp[0] = dp[0] + 1  # Keep the current character as a subsequence of length 1
            dp[1] = dp[1] + 1

    return max(dp)

n = int(input())
s = input()

max_len = 0

# Try flipping each possible substring [i, j]
# This is O(n^2), but we'll just use it to test
for i in range(n):
    for j in range(i, n):
        # Flip substring from i to j
        temp = s[:i] + ('1' if s[i] == '0' else '0') + s[i+1:j+1] + s[j+1:]
        max_len = max(max_len, compute_length(temp))

print(max_len)
