def compute_length(s):
    """Compute the length of the longest alternating subsequence"""
    if not s:
        return 0

    # dp[i]: length of longest alternating subsequence ending at position i
    dp = [1] * len(s)

    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            # We can extend the subsequence
            dp[i] = dp[i-1] + 1

    return max(dp)

