        adj = [[] for _ in range(n + 1)]

        for i in range(m):
            u, v = map(int, input().split())
            adj[u].append(v)
            adj[v].append(u)

        # Dijkstra's algorithm
        import heapq

        def dijkstra(start):
            dist = [float('inf')] * (n + 1)
            dist[start] = 0
            heap = [(0, start)]

            while heap:
                d, u = heapq.heappop(heap)
                if d > dist[u]:
                    continue
                for v in adj[u]:
                    if dist[v] > dist[u] + 1:
                        dist[v] = dist[u] + 1
                        heapq.heappush(heap, (dist[v], v))
            return dist

        dist_a = dijkstra(a)
        dist_b = dijkstra(b)
        dist_c = dijkstra(c)

        # Find edges that are on some shortest path from a to b and b to c
        used_edges = set()

        for u in range(1, n + 1):
            for v in adj[u]:
