def count_mergesort_calls(arr):
    """Count the number of mergesort calls for a given array"""

    def mergesort_calls(arr, l, r):
        # Check if segment [l, r) is sorted
        is_sorted = True
        for i in range(l, r - 1):
            if arr[i] > arr[i + 1]:
                is_sorted = False
                break

        if is_sorted:
            return 1

        # Split and recurse
        mid = (l + r) // 2
        left_calls = mergesort_calls(arr, l, mid)
        right_calls = mergesort_calls(arr, mid, r)

        return left_calls + right_calls

    return mergesort_calls(arr, 0, len(arr))

def solve():
    n, k = map(int, input().split())

    # Try different construction patterns
    # Pattern 1: simple swap construction
    arr1 = list(range(1, n + 1))
    # Swap elements to create more unsorted segments
    # Swap first element with the i-th element for i from 2 to n-1
    for i in range(2, n):
        arr1[0], arr1[i] = arr1[i], arr1[0]

    # Check if this works
    if count_mergesort_calls(arr1) == k:
        print(' '.join(map(str, arr1)))
        return

    # Pattern 2: another construction
    arr2 = list(range(1, n + 1))
    # Create a peak at the start
    for i in range(2, n):
        arr2[i], arr2[i-1] = arr2[i-1], arr2[i]

    if count_mergesort_calls(arr2) == k:
