from collections import deque

def solve():
    # Read input
    n, m = map(int, input().split())

    # Read two rows of the maze
    row1 = input().strip()
    row2 = input().strip()

    # Convert to 2D grid with 1-indexed positions
    grid = [['' for _ in range(2)] for _ in range(n + 1)]

    for i in range(n):
        grid[i + 1][0] = row1[i]
        grid[i + 1][1] = row2[i]

    # Function to convert cell number to (row, col)
    def get_pos(cell):
        if 1 <= cell <= n:
            return (0, cell)
        else:
            return (1, cell - n)

    # Function to convert (row, col) to cell number
    def get_cell(row, col):
        return col + (n + 1) * row

    # Function to check if cell is empty
    def is_empty(row, col):
        return grid[row + 1][col] == '.'

    # Function to get adjacent cells
    def get_neighbors(row, col):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r = row + dr
            c = col + dc
            if 0 <= r < 2 and 0 < c <= n and is_empty(r, c):
                neighbors.append((r, c))
        return neighbors

    # BFS from a starting cell
    def bfs(start_row, start_col):
        # distances to all cells
        dist = [float('inf')] * (2 * (n + 1))
        dist[start_cell] = 0

        queue = deque([start_cell])
        while queue:
            cell = queue.popleft()
            row, col = get_pos(cell)
            for neighbor in get_neighbors(row, col):
                neighbor_cell = get_cell(*neighbor)
                if dist[neighbor_cell] == float('inf'):
                    dist[neighbor_cell] = dist[cell] + 1
                    queue.append(neighbor_cell)

        return dist

    # Process queries
    for _ in range(m):
        v, u = map(int, input().split())

        if v == u:
            print(0)
            continue

        start_row, start_col = get_pos(v)
        end_row, end_col = get_pos(u)

        if start_row == end_row:
            # Same row
            dist = abs(start_col - end_col)
        else:
            # Different rows
            # Run BFS from start
            dist_start = bfs(start_row, start_col)
            dist_end = bfs(end_row, end_col)

            # Find minimum distance
            dist = min(d1 + d2 for d1, d2 in zip(dist_start, dist_end))

        print(dist)

