import sys
import math

def get_divisors(n):
    """Return list of divisors of n in increasing order"""
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    X = int(data[0])
    k = int(data[1])

    # Start with initial sequence S = [X]
    S = [X]

    for _ in range(k):
        if len(S) > 100000:
            break

        # Generate next sequence by taking divisors of each element
        next_S = []
        for num in S:
            next_S.extend(get_divisors(num))

        S = next_S

    # Output first 100000 elements
    print(' '.join(map(str, S[:100000])))

if __name__ == "__main__":
    solve()
"}

