def prime_factors(n):
    """Return the set of prime factors of n"""
    if n == 1:
        return set()

    factors = set()

    # Check for 2 as a factor
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n //= 2

    # Check odd numbers from 3 to sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i

    # If remaining n is > 1, it's a prime factor
    if n > 1:
        factors.add(n)

    return factors

def solve():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return

    idx = 0
    n = int(input[idx])
    idx += 1

    results = []

    for _ in range(n):
        p = int(input[idx])
        q = int(input[idx + 1])
        b = int(input[idx + 2])
        idx += 3

        # Simplify the fraction
        g = math.gcd(p, q)
        simplified_p = p // g
        simplified_q = q // g

        # Get prime factors of denominator
        denom_factors = prime_factors(simplified_q)

        # Get prime factors of base
        base_factors = prime_factors(b)

        # Check if all denominator factors are in base factors
        if denom_factors.issubset(base_factors):
            results.append("Finite")
        else:
            results.append("Infinite")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

