def char_to_idx(c):
    return ord(c) - ord('a')

def idx_to_char(i):
    return chr(ord('a') + i)

# Check if a string is tolerable (no palindromes of length 2 or 3)
def is_tolerable(s):
    # s is a list of indices

    # Check for palindromes of length 2
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    # Check for palindromes of length 3
    for i in range(len(s) - 2):
        if s[i] == s[i+2]:
            return False

    return True

# Find the next tolerable string
# Try to increment from right to left
for i in range(n-1, -1, -1):
    # Try to increase the character at position i
    current_char_idx = char_to_idx(s[i])

    # Try each character that's larger than the current one
    for new_char_idx in range(current_char_idx + 1, p):
        # Create a new string with this character at position i
        new_s = list(char_to_idx(c) for c in s[:i]) + [new_char_idx] + list(char_to_idx(c) for c in s[i+1:])

        # Check if this new string is tolerable
        if is_tolerable(new_s):
            # Check if the rest of the string can be filled with the smallest possible characters
            # While filling, ensure we don't create palindromes
            result = new_s[:i] + [new_char_idx]

            # Fill the remaining positions with the smallest possible characters
            for j in range(i+1, n):
                # Try to fill with the smallest possible character that doesn't create a palindrome
                # Only check positions that have already been filled
                for candidate in range(p):
                    # Check with previous character (if exists)
                    if j > 0 and candidate == result[j-1]:
                        continue
