def f(p, n):
    """Calculate f(p) for a permutation p of length n"""
    return sum(p[i] * (n - 1 - i) for i in range(n))

def generate_permutations(n):
    """Generate all permutations of length n"""
    return [p for p in permutations(range(1, n+1))]

def max_f_value(n):
    """Find the maximum f(p) value for permutations of length n"""
    perms = generate_permutations(n)
    return max(f(p, n) for p in perms)

def find_max_f_permutations(n):
    """Find all permutations of length n with maximum f(p) value"""
    perms = generate_permutations(n)
    max_value = max_f_value(n)
    return [p for p in perms if f(p, n) == max_value]

def lex_order(p):
    """Generate lexicographical order of permutations"""
    return sorted(p)

def solve(n, m):
    """Find the m-th permutation with maximum f(p)"""
    perms = find_max_f_permutations(n)
    return perms[m-1]

n, m = map(int, input().split())
result = solve(n, m)
print(' '.join(map(str, result)))
