    x_max = max(xa, xb)
    y_min = min(ya, yb)
    y_max = max(ya, yb)

    # Count blankets needed
    blankets = 0
    # Check each perimeter point
    for y in range(y_min, y_max + 1):
        for x in range(x_min, x_max + 1):
            # Is (x,y) on the perimeter?
            # Bottom or top (y == y_min or y == y_max)
            if y == y_min or y == y_max:
                # On bottom or top
                if any(abs(x - rx)**2 + abs(y - ry)**2 <= ri**2 for rx, ry, ri in radiators):
                    continue
                else:
                    blankets += 1
            else:
                # On left or right (x == x_min or x == x_max)
