for r in range(R):
    for c in range(C):
        if rows[r][c] == 'B':
            brick_columns[c] = True

# Count contiguous True blocks
count = 0
in_segment = False
for col in brick_columns:
    if col:
        if not in_segment:
            count += 1
            in_segment = True
    else:
        in_segment = False

print(count)

